"""Snap span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def check_step(step: int) -> None:
    """Reject steps that do not divide an hour evenly."""
    if step <= 0 or 60 % step != 0:
        raise ValueError(f"bad step: {step!r}")


def snap_minutes(minutes: int, step: int) -> int:
    """Nearest multiple of step. Halves round up."""
    return (2 * minutes + step) // (2 * step) * step


def round_span(span: Span, step: int) -> Span:
    """Snap both edges. A span that shrinks to nothing is
    rejected by Span with a ValueError."""
    check_step(step)
    return Span(
        snap_minutes(span.start, step),
        snap_minutes(span.end, step)
    )


def duration_text(minutes: int) -> str:
    hours, rest = divmod(minutes, 60)
    return f"{hours}h {rest}m"


def span_label(span: Span) -> str:
    length = duration_text(span.minutes)
    return f"{format_span(span)} ({length})"


def label_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    check_step(step)
    rounded = [round_span(item, step) for item in spans]
    return [span_label(item) for item in rounded]

