# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.rounding import label_spans, round_span


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        spans = [parse_span("09:00-17:00")]
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                label_spans(spans, step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            label_spans([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 15, 30, 60):
            self.assertEqual(len(label_spans([], step)), 0)


class RoundTests(unittest.TestCase):
    def test_nearest_step(self):
        span = parse_span("09:06-17:08")
        self.assertEqual(
            round_span(span, 15), parse_span("09:00-17:15")
        )

    def test_halves_round_up(self):
        span = parse_span("09:15-17:45")
        self.assertEqual(
            round_span(span, 30), parse_span("09:30-18:00")
        )

    def test_end_of_day(self):
        span = parse_span("23:00-24:00")
        self.assertEqual(round_span(span, 30), span)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(parse_span("09:01-09:04"), 15)


class LabelTests(unittest.TestCase):
    def test_label_example(self):
        spans = [parse_span("08:58-17:16")]
        self.assertEqual(
            label_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [
            parse_span("08:00-12:00"),
            parse_span("13:00-13:50")
        ]
        self.assertEqual(
            label_spans(spans, 30),
            ["08:00-12:00 (4h 0m)", "13:00-14:00 (1h 0m)"]
        )
